def sumofFactors(n):
    def is_even(x):
        return x % 2 == 0

    sum_even_factors = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            if is_even(i):
                sum_even_factors += i
            if i != n // i and is_even(n // i):
                sum_even_factors += n // i
    return sum_even_factors

# Example usage and test
assert sumofFactors(18) == 26
```

