def tuple_to_dict(input_tuple):
    """
    Convert a tuple into a dictionary using adjacent elements as key-value pairs.

    Args:
    input_tuple (tuple): The input tuple with an even number of elements.

    Returns:
    dict: A dictionary where adjacent elements of the tuple are key-value pairs.
    """
    # Use dictionary comprehension to pair adjacent elements
    return {input_tuple[i]: input_tuple[i + 1] for i in range(0, len(input_tuple), 2)}

# Test cases
